import{MATIERES}from"./chunk-74ZIK5KQ.js";import{AUTONOME,RACINE}from"./chunk-MENTKLMX.js";var matieres=()=>MATIERES,matieresOuvertes=()=>MATIERES.filter(m=>m.ouverte),trouverMatiere=id=>MATIERES.find(m=>m.id===id)||null,lienMatiere=m=>AUTONOME?"#":RACINE+"matiere.html?m="+encodeURIComponent(m.id),nomCourant=m=>/^[A-Z0-9]+$/.test(m.nom)?m.nom:m.nom.toLowerCase(),index=null;function chapitreCatalogue(id){if(!index){index=new Map;for(let m of MATIERES)for(let n of m.niveaux||[])for(let c of n.chapitres||[])index.has(c.id)||index.set(c.id,{matiere:m,niveau:n,chapitre:c})}return index.get(id)||null}function chapitresDe(m){let plats=[];return(m.niveaux||[]).forEach(n=>n.chapitres.forEach(c=>plats.push(Object.assign({niveau:n.nom,niveauId:n.id},c)))),plats}function trouverChapitre(matiereId,id){let m=trouverMatiere(matiereId);if(!m)return null;let plats=chapitresDe(m),publies=plats.filter(c=>c.fichier),i=publies.findIndex(c=>c.id===id);return{matiere:m,courant:publies[i]||plats.find(c=>c.id===id)||null,prec:i>0?publies[i-1]:null,suiv:i>=0&&i<publies.length-1?publies[i+1]:null}}var chapitresPublies=m=>chapitresDe(m).filter(c=>c.fichier),tousLesChapitres=()=>matieresOuvertes().flatMap(m=>chapitresPublies(m).map(c=>Object.assign({matiere:m},c)));function chapitreComplet(id){let x=chapitreCatalogue(id);return x?Object.assign({matiere:x.matiere,niveau:x.niveau},x.chapitre):null}var nomChapitre=id=>{let x=chapitreCatalogue(id);return x?x.chapitre.titre:id};function lienChapitre(id,ancre){let c=chapitreComplet(id);return c&&c.fichier?RACINE+c.fichier+(ancre?"#"+ancre:""):null}export{matieres,matieresOuvertes,trouverMatiere,lienMatiere,nomCourant,chapitreCatalogue,trouverChapitre,chapitresPublies,tousLesChapitres,chapitreComplet,nomChapitre,lienChapitre};
